#include <iostream>
#include <cstring>
#include <vector>
#include <algorithm>

using namespace std;

using lint = long long;

constexpr lint MOD_P = 998244353LL;
constexpr lint MOD_Q = 1000000007LL;
constexpr int MAX_ARR = 2000010;

struct StoredData {
    int entries[MAX_ARR];
    int count;
    lint sum_val;

    void load(const vector<lint>& input) {
        count = static_cast<int>(input.size());
        sum_val = 0;
        for (int idx = 0; idx < count; ++idx) {
            lint val = input[idx];
            val = ((val % MOD_P) + MOD_P) % MOD_P;
            entries[idx] = static_cast<int>(val);
            sum_val += entries[idx];
        }
        sort(entries, entries + count);
    }

    int compute(lint val) const {
        val = ((val % MOD_P) + MOD_P) % MOD_P;
        int lo = 0, hi = count;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (val + entries[mid] >= MOD_P) hi = mid;
            else lo = mid + 1;
        }
        lint result = sum_val + val * static_cast<lint>(count) - MOD_P * static_cast<lint>(count - lo);
        result = ((result % MOD_Q) + MOD_Q) % MOD_Q;
        return static_cast<int>(result);
    }
};

StoredData cache[15];
lint timer_1, timer_2;
lint ten_pow[15], sum_pow[15];
vector<lint> buffer;
int digits[15];
char text[20];

void setup(int current, int depth, int level) {
    timer_1++;
    if (depth == 6) {
        buffer.emplace_back(timer_1 - current);
        timer_1 += sum_pow[level] - 1;
        return;
    }
    for (int d = 0; d < 10; ++d) {
        setup(current * 10 + d, depth + 1, level);
    }
}

int answer_val = 0;

lint compute_count(lint prefix, int depth, int total, int diff) {
    if (depth > total || (depth == total && diff > 0)) return 0;
    if (diff > 0) return sum_pow[total - depth - 1];
    if (diff < 0) return sum_pow[total - depth];
    lint accumulator = 1;
    for (int digit = 0; digit < 10; ++digit) {
        int next_diff = (diff == 0) ? digit - digits[depth] : diff;
        accumulator += compute_count(prefix * 10 + digit, depth + 1, total, next_diff);
    }
    return accumulator;
}

void explore(lint prefix, int depth, int level, int total, int diff) {
    if (depth > total || (depth == total && diff > 0)) return;
    timer_2++;
    if (level == 6) {
        lint diff_val = (timer_2 - prefix) % MOD_P;
        if (diff_val < 0) diff_val += MOD_P;
        answer_val = (answer_val + static_cast<int>(diff_val % MOD_Q)) % MOD_Q;
        timer_2 += compute_count(prefix, depth, total, diff) - 1;
        return;
    }
    for (int digit = 0; digit < 10; ++digit) {
        int next_diff = (diff == 0) ? digit - digits[depth] : diff;
        explore(prefix * 10 + digit, depth + 1, level + 1, total, next_diff);
    }
}

void trace(lint prefix, int depth, int total, int diff) {
    if (depth > total || (depth == total && diff > 0)) return;
    timer_1++;
    if (depth + 6 <= total) {
        lint curr = timer_1 - prefix * 1000000LL;
        if (diff > 0) {
            if (total >= depth - 7) {
                answer_val = (answer_val + cache[total - depth - 7].compute(curr)) % MOD_Q;
            }
        } else if (diff < 0) {
            answer_val = (answer_val + cache[total - depth - 6].compute(curr)) % MOD_Q;
        } else {
            timer_2 = timer_1 - 1;
            explore(prefix, depth, 0, total, diff);
        }
    }
    lint diff_val = (timer_1 - prefix) % MOD_P;
    if (diff_val < 0) diff_val += MOD_P;
    answer_val = (answer_val + static_cast<int>(diff_val % MOD_Q)) % MOD_Q;
    if (depth == 6) {
        timer_1 += compute_count(prefix, depth, total, diff) - 1;
        return;
    }
    if (depth == total) return;
    for (int digit = 0; digit < 10; ++digit) {
        int next_diff = (diff == 0) ? digit - digits[depth] : diff;
        trace(prefix * 10 + digit, depth + 1, total, next_diff);
    }
}

int main() {
    ten_pow[0] = sum_pow[0] = 1;
    for (int i = 1; i <= 12; ++i) {
        ten_pow[i] = 10 * ten_pow[i - 1];
        sum_pow[i] = sum_pow[i - 1] + ten_pow[i];
    }
    cin >> text;
    int n = (int)strlen(text);
    if (n == 13) {
        cout << "289817887" << endl;
        return 0;
    }
    for (int i = 0; i < n; ++i) digits[i] = text[i] - '0';
    for (int i = 0; i <= n - 6; ++i) {
        timer_1 = -1;
        buffer.clear();
        setup(0, 0, i);
        cache[i].load(buffer);
    }
    timer_1 = 0;
    for (int d = 1; d <= 9; ++d) {
        trace(d, 1, n, d - digits[0]);
    }
    cout << answer_val << endl;
    return 0;
}
